import test from 'node:test';import assert from 'node:assert/strict';import {mkdtemp,mkdir,writeFile,rm} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';
import {captureSources} from '../../dist/source/roots.js';import {SourceIndex} from '../../dist/source/typescript-index.js';import {references,dynamicEdges} from '../../dist/source/references.js';import {sourceMapping} from '../../dist/source/source-maps.js';
async function fixture(t,text){const root=await mkdtemp(path.join(os.tmpdir(),'cocos p4 review '));t.after(()=>rm(root,{recursive:true,force:true}));await mkdir(path.join(root,'assets'));await writeFile(path.join(root,'assets/A.ts'),text);return root;}
test('review: selected engine cc module links project inheritance and methods',async t=>{const root=await fixture(t,'import {Component} from "cc";export class Child extends Component {}');const engine=path.join(root,'engine');await mkdir(path.join(engine,'cocos/core'),{recursive:true});await mkdir(path.join(engine,'exports'));await writeFile(path.join(engine,'cocos/core/global-exports.ts'),"const engineVersion='3.7.3';");await writeFile(path.join(engine,'cocos/core/component.ts'),'export class Component {getComponent(){return null;}}');await writeFile(path.join(engine,'exports/base.ts'),'export {Component} from "../cocos/core/component";');const index=new SourceIndex(await captureSources(root,{creatorVersion:'3.7.3',engineRoot:engine}));const child=index.resolve('Child');assert.equal(index.hierarchy(child.id)[0].name,'Component');assert.equal(index.method(child.id,'getComponent').location.owner.kind,'engine');});
test('review: source maps clear mapped points across unmapped segments',async t=>{const root=await fixture(t,'export class A{}');const file=path.join(root,'assets/out.js');await writeFile(file,'var a=1; var b=2;\n//# sourceMappingURL=out.js.map');await writeFile(file+'.map',JSON.stringify({version:3,sources:['A.ts'],names:[],mappings:'AAAA,Q,IAAA'}));const c=await captureSources(root,{creatorVersion:'3.7.3'}),p=path.join(c.root,'assets/out.js');assert.equal(sourceMapping(c,p,1,1).status,'mapped');assert.equal(sourceMapping(c,p,1,10).status,'position-unmapped');assert.equal(sourceMapping(c,p,1,13).status,'mapped');});
test('review: literal element references are semantic; dynamic component lookups are explicit',async t=>{const root=await fixture(t,'class A{count=0;}class Other{count=0;} declare let a:A,b:Other,node:any,dynamicName:string; a.count++;a["count"]++;b["count"]++;node.getComponent(dynamicName);node.getComponent(A);node.getComponentInChildren(dynamicName+"x");');const index=new SourceIndex(await captureSources(root,{creatorVersion:'3.7.3'}));assert.equal(references(index,index.resolve('A').id,'count').length,3);const edges=dynamicEdges(index);assert.equal(edges.filter(e=>e.reason==='dynamic-component-type').length,2);});
test('review: static and arrow methods expose bodies; accessors are not callable event handlers',async t=>{const root=await fixture(t,'export class A {static create(){return new A();} onClick=()=>{return 1;};get value(){return 7;}}');const index=new SourceIndex(await captureSources(root,{creatorVersion:'3.7.3'})),a=index.resolve('A');assert.equal(index.method(a.id,'create').status,'implementation');assert.equal(index.method(a.id,'onClick').status,'implementation');assert.equal(index.method(a.id,'value').body,null);assert.equal(index.method(a.id,'value').status,'non-callable');});
test('source permission checks run before reading engine version through a directory symlink',async t=>{const root=await fixture(t,'export class A{}'),outside=await mkdtemp(path.join(os.tmpdir(),'outside engine '));t.after(()=>rm(outside,{recursive:true,force:true}));await writeFile(path.join(outside,'global-exports.ts'),"const engineVersion='3.8.0';");const engine=path.join(root,'engine');await mkdir(path.join(engine,'cocos'),{recursive:true});const {symlink}=await import('node:fs/promises');await symlink(outside,path.join(engine,'cocos/core'),process.platform==='win32'?'junction':'dir');await assert.rejects(captureSources(root,{creatorVersion:'3.7.3',engineRoot:engine}),e=>e.code==='PATH_OUTSIDE_PROJECT');});
